			a += " "
		}
	} else {
		// American: optional parentheses, symbol, number.
		if negative {
			a = "(" + symbol + formatCents(cents, ",", ".") + ")"
		} else {
			a = symbol + formatCents(cents, ",", ".") + " "
		}
	}
	return a
}
```

